 app.post('/api/v1/attendance/manual',checkInLimit,requirePermission('checkin.manual'),asyncRoute(async(req,res)=>{
  const {memberId}=z.object({memberId:uuid}).strict().parse(req.body);
  const result=await db.transaction(async c=>{
   await c.query('SELECT pg_advisory_xact_lock(hashtext($1))',[memberId]);
   const member=(await c.query("SELECT m.id,m.first_name,m.last_name,u.status FROM members m JOIN users u ON u.id=m.user_id WHERE m.id=$1 FOR UPDATE",[memberId])).rows[0];
   if(!member)throw Object.assign(new Error('Member was not found'),{status:404});
   const branch=(await c.query(defaultBranchQuery)).rows[0]?.id;
   if(!branch)throw Object.assign(new Error('Reception check-in is not configured'),{status:422,code:'RECEPTION_REQUIRED'});
   const deny=async(message,code,httpStatus)=>{
    const visit=await recordDeniedAttendance(c,{memberId:member.id,branchId:branch,scannerUserId:req.actor.id,method:'manual',reason:message});
    await audit(c,req,'attendance.manual_check_in_denied','attendance',visit.id,{memberId:member.id,memberName:`${member.first_name} ${member.last_name}`,branchId:branch,reason:message,code});
    return{denied:true,httpStatus,code,message};
   };
   if(member.status!=='active')return deny('Member account is not active','ACCESS_DENIED',403);
   const valid=(await c.query("SELECT 1 FROM subscriptions WHERE member_id=$1 AND status='active' AND starts_at<=now() AND ends_at>now() AND NOT EXISTS(SELECT 1 FROM subscription_freezes f WHERE f.released_at IS NULL AND f.subscription_id=subscriptions.id AND now()>=f.starts_at AND now()<f.ends_at)",[memberId])).rowCount;
   if(!valid)return deny('Member does not have an active membership','ACCESS_DENIED',403);
   const existing=(await c.query("SELECT id,checked_in_at FROM attendance WHERE member_id=$1 AND status='completed' AND checked_in_at::date=current_date ORDER BY checked_in_at DESC LIMIT 1",[memberId])).rows[0];
   if(existing)return{...existing,duplicate:true,member:{id:member.id,firstName:member.first_name,lastName:member.last_name}};
   const visit=(await c.query("INSERT INTO attendance(member_id,branch_id,checked_in_at,scanner_user_id,method,status) VALUES($1,$2,now(),$3,'manual','completed') RETURNING id,checked_in_at",[memberId,branch,req.actor.id])).rows[0];
   await audit(c,req,'attendance.manual_check_in','attendance',visit.id,{memberId,memberName:`${member.first_name} ${member.last_name}`,branchId:branch});
   return{...visit,member:{id:member.id,firstName:member.first_name,lastName:member.last_name}};
  },'SERIALIZABLE');
  if(result.denied)return res.status(result.httpStatus).json({error:{code:result.code,message:result.message,requestId:req.requestId}});
  res.status(result.duplicate?200:201).json({data:result});
 }));
