 app.get('/api/v1/appointments',asyncRoute(async(req,res)=>{const memberId=await ownMember(req.actor);const trainer=(await db.query('SELECT id FROM trainers WHERE user_id=$1',[req.actor.id])).rows[0]?.id;const filter=req.actor.roles.includes('admin')?{sql:'TRUE',args:[]}:memberId?{sql:'a.member_id=$1',args:[memberId]}:trainer?{sql:'a.trainer_id=$1',args:[trainer]}:{sql:'FALSE',args:[]};const{rows}=await db.query(`SELECT a.*,concat(m.first_name,' ',m.last_name) member_name,concat(t.first_name,' ',t.last_name) trainer_name FROM appointments a JOIN members m ON m.id=a.member_id JOIN trainers t ON t.id=a.trainer_id WHERE ${filter.sql} ORDER BY starts_at`,filter.args);res.json({data:rows})}));
