 app.get('/api/v1/receipts/:reference',asyncRoute(async(req,res)=>{const reference=z.string().min(8).max(200).parse(req.params.reference),memberId=await ownMember(req.actor);if(!memberId)throw Object.assign(new Error('Member profile required'),{status:403});const membership=(await db.query("SELECT py.receipt_number,py.provider_reference reference,py.amount_minor,py.membership_amount_minor,py.registration_fee_minor,py.currency,py.paid_at issued_at,p.name item,concat(m.first_name,' ',m.last_name) member_name,'Membership' kind FROM payments py JOIN membership_plans p ON p.id=py.plan_id JOIN members m ON m.id=py.member_id WHERE py.provider_reference=$1 AND py.member_id=$2 AND py.status='successful'",[reference,memberId])).rows[0];if(membership)return res.json({data:membership});const event=(await db.query("SELECT r.receipt_number,r.provider_reference reference,r.amount_minor,e.currency,r.registered_at issued_at,e.title item,concat(m.first_name,' ',m.last_name) member_name,'Event' kind FROM event_registrations r JOIN events e ON e.id=r.event_id JOIN members m ON m.id=r.member_id WHERE r.provider_reference=$1 AND r.member_id=$2 AND r.status='confirmed'",[reference,memberId])).rows[0];if(event)return res.json({data:event});res.status(202).json({data:null,message:'Payment confirmation is still processing'})}));
