 app.get('/api/v1/audit',requirePermission('audit.view'),asyncRoute(async(req,res)=>{const limit=z.coerce.number().int().min(1).max(500).default(200).parse(req.query.limit);const{rows}=await db.query(`SELECT a.id,a.action,a.entity_type,a.entity_id,a.new_values,a.ip,a.request_id,a.created_at,u.email actor_email,COALESCE(concat_ws(' ',st.first_name,st.last_name),concat_ws(' ',t.first_name,t.last_name),concat_ws(' ',m.first_name,m.last_name),u.email) actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id LEFT JOIN staff st ON st.user_id=u.id LEFT JOIN trainers t ON t.user_id=u.id LEFT JOIN members m ON m.user_id=u.id WHERE a.action<>'member.profile_updated' ORDER BY a.created_at DESC LIMIT $1`,[limit]);res.json({data:rows})}));
 app.get('/api/v1/reports/summary',requirePermission('reports.view'),asyncRoute(async(req,res)=>{const from=z.string().date().default(new Date(Date.now()-30*86400000).toISOString().slice(0,10)).parse(req.query.from),to=z.string().date().default(new Date().toISOString().slice(0,10)).parse(req.query.to);const{rows}=await db.query("SELECT (SELECT count(*) FROM members WHERE joined_at::date BETWEEN $1 AND $2) new_members,(SELECT count(*) FROM attendance WHERE created_at::date BETWEEN $1 AND $2 AND status<>'denied') visits,(SELECT COALESCE(sum(amount_minor),0) FROM payments WHERE paid_at::date BETWEEN $1 AND $2 AND status='successful') revenue_minor",[from,to]);res.json({data:{from,to,...rows[0],revenue:Number(rows[0].revenue_minor)/100,currency:'NGN'}})}));
